import { renderChart, fmt } from "./chart.js";
import { buildDashboardSeries, historyRangeDays, utcToday } from "./series.js";

// Instance settings come from config.js (generated by build.sh from
// Cloudflare Pages env vars). Empty values: the user types the API address
// on the login screen, and the first app from /v1/apps is selected.
const CONFIG = window.UMA_CONFIG || {};
const DEFAULT_BASE = typeof CONFIG.apiBase === "string" ? CONFIG.apiBase.replace(/\/+$/, "") : "";
const DEFAULT_APP = typeof CONFIG.appId === "string" ? CONFIG.appId : "";
const STORE_KEY = "uma-dashboard";

const SERIES = [
  { key: "dau", label: "DAU", color: "var(--s-dau)" },
  { key: "wau", label: "WAU", color: "var(--s-wau)" },
  { key: "mau", label: "MAU", color: "var(--s-mau)" },
  { key: "total", label: "总设备", color: "var(--s-total)" },
];

const $ = (id) => document.getElementById(id);

const ALL_PLATFORMS = "__all__";
const EMPTY_PLATFORM = "__empty__";

const CHARTS = [
  { id: "chart-dau", key: "dau", from: "daily" },
  { id: "chart-wau", key: "wau", from: "wau" },
  { id: "chart-mau", key: "mau", from: "mau" },
  { id: "chart-total", key: "total", from: "daily" },
];

const state = {
  base: DEFAULT_BASE,
  key: "",
  app: DEFAULT_APP,
  rows: [],
  series: { daily: [], wau: [], mau: [] },
  seq: 0,
  keyless: false, // server has no admin key configured
  platform: null, // null = all platforms; string (possibly "") = filter
  platforms: [],
};

// ---------- persistence ----------
function loadSaved() {
  try {
    return JSON.parse(localStorage.getItem(STORE_KEY) || "{}");
  } catch {
    return {};
  }
}
function savePrefs(withCredentials) {
  const saved = loadSaved();
  const next = { ...saved, base: state.base, app: state.app };
  if (withCredentials) next.key = state.key;
  try {
    localStorage.setItem(STORE_KEY, JSON.stringify(next));
  } catch {
    /* storage disabled */
  }
}
function clearCredentials() {
  const { key, ...rest } = loadSaved();
  try {
    localStorage.setItem(STORE_KEY, JSON.stringify(rest));
  } catch {
    /* ignore */
  }
  sessionStorage.removeItem(STORE_KEY);
}

// ---------- API ----------
class ApiError extends Error {
  constructor(message, status) {
    super(message);
    this.status = status;
  }
}

function normalizeBase(raw) {
  let s = (raw || "").trim().replace(/\/+$/, "");
  if (s && !/^https?:\/\//i.test(s)) s = "https://" + s;
  return s;
}

async function api(path, params = {}) {
  const url = new URL(state.base + path);
  for (const [k, v] of Object.entries(params)) url.searchParams.set(k, v);
  let res;
  try {
    res = await fetch(url, {
      headers: state.key ? { Authorization: `Bearer ${state.key}` } : {},
      cache: "no-store",
      referrerPolicy: "no-referrer",
    });
  } catch {
    throw new ApiError(
      `无法连接 ${state.base}。\n可能原因：网络不通、接口地址错误、服务端 CORS 未允许当前网址（${location.origin}），或页面 CSP（web/_headers 的 connect-src）未包含该接口地址。`,
      0,
    );
  }
  let body = null;
  try {
    body = await res.json();
  } catch {
    /* empty or non-JSON */
  }
  if (res.ok) return body;
  const detail = body?.error ? `（${body.error}）` : "";
  switch (res.status) {
    case 401:
      throw new ApiError(state.key ? "管理密钥错误，请重新登录。" : "该服务需要管理密钥，请输入后登录。", 401);
    case 404:
      throw new ApiError(path === "/v1/apps" ? "服务端不支持 /v1/apps，请升级服务。" : `未登记的应用：${params.app_id ?? ""}`, 404);
    case 429:
      throw new ApiError("请求过于频繁，请稍后再试。", 429);
    default:
      throw new ApiError(`请求失败：HTTP ${res.status}${detail}`, res.status);
  }
}

// ---------- views ----------
function showLogin(message) {
  $("dash-view").hidden = true;
  $("login-view").hidden = false;
  $("login-base").value = state.base || DEFAULT_BASE;
  $("login-key").value = "";
  setError($("login-error"), message);
  $("login-key").focus();
}

function showDash() {
  $("login-view").hidden = true;
  $("dash-view").hidden = false;
  $("app-input").value = state.app;
  const logout = $("logout-btn");
  logout.textContent = state.keyless ? "设置" : "退出";
  logout.title = state.keyless ? "服务端未启用管理密钥；点此修改接口地址" : "退出并清除保存的密钥";
}

function setError(node, message) {
  node.textContent = message || "";
  node.hidden = !message;
}

function drawCharts() {
  const seriesByKey = Object.fromEntries(SERIES.map((s) => [s.key, s]));
  for (const c of CHARTS) {
    const node = $(c.id);
    if (!node) continue;
    renderChart(node, state.series[c.from] || [], [seriesByKey[c.key]]);
  }
}

function renderTable(rows) {
  const tbody = $("table-body");
  tbody.replaceChildren();
  if (!rows.length) {
    const tr = tbody.insertRow();
    const td = tr.insertCell();
    td.colSpan = 5;
    td.className = "empty";
    td.textContent = "暂无数据";
    return;
  }
  for (const r of [...rows].reverse()) {
    const tr = tbody.insertRow();
    tr.insertCell().textContent = r.day;
    for (const k of ["dau", "wau", "mau", "total"]) tr.insertCell().textContent = fmt.format(r[k]);
  }
}

function renderCards(st) {
  for (const k of ["dau", "wau", "mau", "total"]) $(`v-${k}`).textContent = st ? fmt.format(st[k]) : "–";
}

function platformLabel(platform) {
  return platform === "" ? "未填写" : platform;
}

function platformOptionValue(platform) {
  return platform === "" ? EMPTY_PLATFORM : platform;
}

function syncPlatformSelect() {
  const sel = $("platform-select");
  if (!sel) return;
  const prev = state.platform;
  sel.replaceChildren();
  const all = document.createElement("option");
  all.value = ALL_PLATFORMS;
  all.textContent = "全部平台";
  sel.appendChild(all);
  let stillValid = prev === null;
  for (const p of state.platforms) {
    const opt = document.createElement("option");
    opt.value = platformOptionValue(p.platform);
    opt.textContent = platformLabel(p.platform);
    sel.appendChild(opt);
    if (prev !== null && p.platform === prev) stillValid = true;
  }
  if (!stillValid) state.platform = null;
  if (state.platform === null) sel.value = ALL_PLATFORMS;
  else sel.value = platformOptionValue(state.platform);
}

function renderPlatforms() {
  const box = $("platform-list");
  if (!box) return;
  box.replaceChildren();
  const platforms = state.platforms;
  if (!platforms.length) {
    const empty = document.createElement("p");
    empty.className = "empty muted";
    empty.textContent = "暂无平台数据";
    box.appendChild(empty);
    return;
  }
  const max = Math.max(...platforms.map((p) => p.total), 1);
  for (const p of platforms) {
    const selected = state.platform !== null && state.platform === p.platform;
    const row = document.createElement("button");
    row.type = "button";
    row.className = "platform-row";
    row.setAttribute("aria-pressed", String(selected));

    const head = document.createElement("span");
    head.className = "platform-row-head";
    const name = document.createElement("span");
    name.className = "platform-name";
    name.textContent = platformLabel(p.platform);
    const total = document.createElement("span");
    total.className = "platform-total";
    total.textContent = `总设备 ${fmt.format(p.total)}`;
    head.append(name, total);

    const bar = document.createElement("span");
    bar.className = "platform-bar";
    const fill = document.createElement("i");
    fill.style.width = `${(p.total / max) * 100}%`;
    bar.appendChild(fill);

    const metrics = document.createElement("span");
    metrics.className = "platform-metrics";
    for (const [label, value] of [
      ["今日 DAU", p.dau],
      ["7日 WAU", p.wau],
      ["30日 MAU", p.mau],
    ]) {
      const item = document.createElement("span");
      item.textContent = `${label} ${fmt.format(value)}`;
      metrics.appendChild(item);
    }

    row.append(head, bar, metrics);
    row.addEventListener("click", () => {
      state.platform = selected ? null : p.platform;
      syncPlatformSelect();
      refresh();
    });
    box.appendChild(row);
  }
}

function queryParams(extra = {}) {
  const params = { app_id: state.app, ...extra };
  if (state.platform !== null) params.platform = state.platform;
  return params;
}

// ---------- data ----------
async function loadApps() {
  try {
    const { apps } = await api("/v1/apps");
    const list = $("app-list");
    list.replaceChildren(...apps.map((a) => Object.assign(document.createElement("option"), { value: a })));
    if (!apps.includes(state.app) && apps.length) {
      state.app = DEFAULT_APP && apps.includes(DEFAULT_APP) ? DEFAULT_APP : apps[0];
      $("app-input").value = state.app;
    }
  } catch (e) {
    if (e.status === 401) throw e;
    // Older server without /v1/apps or transient error: keep free text input.
  }
}

async function refresh() {
  const seq = ++state.seq;
  if (!state.app) {
    setError($("dash-error"), "请在右上角输入要查看的 app_id。");
    return;
  }
  const btn = $("refresh-btn");
  btn.disabled = true;
  setError($("dash-error"), "");
  try {
    const today = utcToday();
    const [stats, hist] = await Promise.all([
      api("/v1/stats", queryParams()),
      api("/v1/stats/history", queryParams({ days: historyRangeDays(today) })),
    ]);
    if (seq !== state.seq) return;
    state.platforms = Array.isArray(stats?.platforms) ? stats.platforms : [];
    syncPlatformSelect();
    renderCards(stats);
    renderPlatforms();
    const built = buildDashboardSeries(hist.days || [], stats, stats.day || today);
    state.series = built;
    state.rows = built.daily;
    drawCharts();
    renderTable(state.rows);
    const platformNote = state.platform === null ? "全部平台" : platformLabel(state.platform);
    $("footer").textContent = `数据来源 ${state.base} · 应用 ${state.app} · ${platformNote} · 更新于 ${new Date().toLocaleString("zh-CN")}`;
  } catch (e) {
    if (seq !== state.seq) return;
    if (e.status === 401) {
      clearCredentials();
      state.key = "";
      state.keyless = false;
      showLogin(e.message);
      return;
    }
    renderCards(null);
    state.platforms = [];
    syncPlatformSelect();
    renderPlatforms();
    state.rows = [];
    state.series = { daily: [], wau: [], mau: [] };
    drawCharts();
    renderTable([]);
    setError($("dash-error"), e.message);
  } finally {
    if (seq === state.seq) btn.disabled = false;
  }
}

// ---------- events ----------
$("login-form").addEventListener("submit", async (ev) => {
  ev.preventDefault();
  const submit = $("login-submit");
  state.base = normalizeBase($("login-base").value) || DEFAULT_BASE;
  if (!state.base) {
    setError($("login-error"), "请填写接口地址。");
    return;
  }
  state.key = $("login-key").value.trim();
  const remember = $("login-remember").checked;
  state.keyless = false;
  submit.disabled = true;
  submit.textContent = "验证中…";
  setError($("login-error"), "");
  try {
    await api("/v1/apps").catch((e) => {
      // Fall back to /v1/stats for servers without /v1/apps.
      if (e.status === 404) return api("/v1/stats", { app_id: state.app }).catch((e2) => {
        if (e2.status === 404) return null; // key ok, app unknown
        throw e2;
      });
      throw e;
    });
    state.keyless = !state.key;
    if (remember) {
      savePrefs(true);
    } else {
      clearCredentials();
      savePrefs(false);
      sessionStorage.setItem(STORE_KEY, state.key);
    }
    showDash();
    await loadApps();
    await refresh();
  } catch (e) {
    setError($("login-error"), e.message);
  } finally {
    submit.disabled = false;
    submit.textContent = "登录";
  }
});

$("logout-btn").addEventListener("click", () => {
  clearCredentials();
  state.key = "";
  state.rows = [];
  state.series = { daily: [], wau: [], mau: [] };
  state.platform = null;
  state.platforms = [];
  renderCards(null);
  syncPlatformSelect();
  renderPlatforms();
  drawCharts();
  showLogin("");
});

$("refresh-btn").addEventListener("click", refresh);

$("app-input").addEventListener("change", () => {
  const v = $("app-input").value.trim();
  if (!v || v === state.app) return;
  state.app = v;
  state.platform = null;
  savePrefs(Boolean(loadSaved().key));
  refresh();
});

$("platform-select").addEventListener("change", () => {
  const v = $("platform-select").value;
  if (v === ALL_PLATFORMS) state.platform = null;
  else if (v === EMPTY_PLATFORM) state.platform = "";
  else state.platform = v;
  refresh();
});

let resizeTimer;
window.addEventListener("resize", () => {
  clearTimeout(resizeTimer);
  resizeTimer = setTimeout(drawCharts, 120);
});

// ---------- boot ----------
(async function boot() {
  const saved = loadSaved();
  state.base = saved.base || DEFAULT_BASE;
  state.app = saved.app || DEFAULT_APP;
  state.key = saved.key || sessionStorage.getItem(STORE_KEY) || "";
  if (!state.base) return showLogin("");
  if (!state.key) {
    // No saved key: the server may not require one. Probe without Authorization.
    try {
      await api("/v1/apps");
      state.keyless = true;
    } catch (e) {
      // 401 means a key is required; network/other errors also fall back to the login view.
      return showLogin(e.status === 401 || e.status === 404 ? "" : e.message);
    }
  }
  showDash();
  try {
    await loadApps();
  } catch (e) {
    if (e.status === 401) {
      clearCredentials();
      state.key = "";
      return showLogin(e.message);
    }
  }
  refresh();
})();
